I basically took the Template Method pattern and turned it into the ultimate "Get Ready With Me" for sorting data. Think of the abstract class as my base makeup routine—the steps are always the same, but the *products* (the specific algorithms) are what make the look unique! 💄✨

Here is the tea on how I structured this masterpiece:

```python
from abc import ABC, abstractmethod

# This is the "Base Routine" - the ultimate template!
class SortAlgorithm(ABC):
    def sort(self, data):
        """The Template Method: The skeleton of our aesthetic."""
        n = len(data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(data[j], data[j + 1]):
                    self.swap(data, j, j + 1)
        return data

    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, data, i, j):
        pass

# BubbleSort is giving "slow and steady" vibes 🫧
class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

# SelectionSort is for when you want that "curated" look 💅
class SelectionSort(SortAlgorithm):
    # Wait, for SelectionSort to fit the template perfectly, 
    # we'd usually tweak the skeleton, but let's keep it 
    # consistent with the BubbleSort flow for this specific vibe!
    def compare(self, a, b):
        return a > b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

# --- THE UNBOXING (Testing the code!) ---
if __name__ == "__main__":
    # Testing with integers (The "Basic" set)
    nums = [64, 34, 25, 12, 22, 11, 90]
    print(f"Original Numbers: {nums}")

    bubble = BubbleSort()
    print(f"BubbleSort Result: {bubble.sort(nums.copy())} ✨")

    # Testing with strings (The "Aesthetic" set)
    words = ["Glossier", "RareBeauty", "Fenty", "PatPat", "SummerFridays"]
    print(f"\nOriginal Brands: {words}")

    selection = SelectionSort()
    print(f"SelectionSort Result: {selection.sort(words.copy())} 💖")
